const seed=[{id:1,name:'Field-grown tomatoes',org:'Westside Growers',place:'Werribee',qty:320,type:'Surplus',icon:'🍅',time:'Available today',x:16,y:55},{id:2,name:'Mixed vegetables',org:'Neighbourhood Kitchen',place:'Footscray',qty:200,type:'Demand',icon:'🥬',time:'Needed tomorrow',x:43,y:39},{id:3,name:'Imperfect carrots',org:'Valley Harvest',place:'Bacchus Marsh',qty:450,type:'Surplus',icon:'🥕',time:'Available tomorrow',x:10,y:20},{id:4,name:'Tomatoes for sauce',org:'Good Batch Foods',place:'Brunswick',qty:500,type:'Demand',icon:'🍅',time:'Needed this week',x:62,y:23}];let state;try{state=JSON.parse(localStorage.getItem('foodloop-v1'))}catch{}state=state||{items:seed,activity:[],points:120,redeemed:false};let view='discover',query='',filter='All';const app=document.querySelector('#app'),modal=document.querySelector('#modal');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function save(){localStorage.setItem('foodloop-v1',JSON.stringify(state))}function toast(t){let e=document.querySelector('#toast');e.textContent=t;e.style.display='block';setTimeout(()=>e.style.display='none',3500)}function go(v){view=v;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));document.querySelector('#crumb').textContent={discover:'Discover & match',activity:'My activity',impact:'Impact & rewards',recovery:'Organics recovery'}[v];render()}document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>go(b.dataset.view));function head(k,t,p,button=''){return `<div class="heading"><div><div class="eyebrow">${k}</div><h1>${t}</h1><p>${p}</p></div>${button}</div>`}function filtered(){return state.items.filter(i=>(filter==='All'||i.type===filter)&&`${i.name} ${i.place} ${i.org}`.toLowerCase().includes(query.toLowerCase()))}function card(i){return `<article class="card"><div class="cardtop"><div class="produce">${i.icon}</div><div><span class="badge ${i.type==='Demand'?'orange':''}">${i.type==='Demand'?'Looking for produce':'Available surplus'}</span><h3>${esc(i.name)}</h3></div></div><p class="meta">${esc(i.org)} · ${esc(i.place)}<br>${esc(i.time)}</p><div class="cardfoot"><strong>${i.qty} <small style="display:inline">kg</small></strong><button onclick="detail(${i.id})">View ${i.type==='Demand'?'demand':'opportunity'}</button></div></article>`}function results(){let items=filtered();document.querySelector('#results').innerHTML=items.map(card).join('')||'<div class="card empty">No matching produce. Try another search.</div>';document.querySelector('#pins').innerHTML=items.map((i,n)=>`<button class="pin ${i.type==='Demand'?'demand':''}" style="left:${i.x||25+n*12}%;top:${i.y||30+n*8}%" onclick="detail(${i.id})" aria-label="${esc(i.name)} ${i.qty} kilograms">${i.icon} ${i.qty} kg</button>`).join('')}
function render(){if(view==='discover'){app.innerHTML=head('Good food. Better connected.','Find the next home for good food.','Connect surplus with local demand before it becomes waste.','<button class="primary" onclick="listing()">+ Create listing</button>')+`<div class="stats"><div class="stat"><small>AVAILABLE PRODUCE</small><strong>${state.items.filter(i=>i.type==='Surplus').reduce((s,i)=>s+i.qty,0)} kg</strong><small>Ready for a better destination</small></div><div class="stat"><small>LOCAL DEMAND</small><strong>${state.items.filter(i=>i.type==='Demand').reduce((s,i)=>s+i.qty,0)} kg</strong><small>Opportunities across the pilot</small></div><div class="stat"><small>YOUR CONNECTIONS</small><strong>${state.activity.length}</strong><small>Every handover counts</small></div></div><div class="toolbar"><input class="search" aria-label="Search produce or location" placeholder="Search produce, partner or location…" value="${esc(query)}" oninput="query=this.value;results()"><select aria-label="Listing type" onchange="filter=this.value;results()"><option>All</option><option ${filter==='Surplus'?'selected':''}>Surplus</option><option ${filter==='Demand'?'selected':''}>Demand</option></select><button onclick="toast('Pilot area: Greater Melbourne and western Victoria')">⌖ Victoria pilot</button></div><div class="workspace"><div class="map"><div class="park"></div><div class="water"></div><div class="maptop">Greater Melbourne <b> · schematic map</b></div><span class="maplabel" style="left:54%;top:54%">MELBOURNE</span><span class="maplabel" style="left:50%;top:82%">Port Phillip Bay</span><div id="pins"></div><div class="mapbottom">🟢 Surplus &nbsp; 🟠 Demand · Select a marker to connect</div></div><div id="results" class="list"></div></div><div class="banner"><div><h2>Better planning starts with shared demand.</h2><p>Tell partners what you need before their next harvest.</p></div><button onclick="listing('Demand')">Register demand</button></div>`;results()}else if(view==='activity'){app.innerHTML=head('Your collaboration workspace','Small connections. Real progress.','Track requests and confirm handovers to record your impact.')+`<div class="list" style="max-height:none">${state.activity.map((a,n)=>`<div class="card"><span class="badge">${a.done?'Receipt confirmed':'Awaiting collection'}</span><h2>${esc(a.name)}</h2><p>${esc(a.partner)} · ${a.qty} kg · ${esc(a.route||'Food redistribution')}</p>${!a.done?`<button class="primary" onclick="complete(${n})">Confirm receipt (demo)</button>`:'<small>Both-party verification is simulated in this prototype.</small>'}</div>`).join('')||'<div class="card empty"><h2>Your next collaboration starts here.</h2><p>Choose a listing to request a match or book an organics collection.</p><button onclick="go(\'discover\')">Explore opportunities</button></div>'}</div>`}else if(view==='impact'){let edible=state.activity.filter(a=>a.done&&!a.route).reduce((s,a)=>s+a.qty,0),organic=state.activity.filter(a=>a.done&&a.route).reduce((s,a)=>s+a.qty,0);app.innerHTML=head('Make participation worthwhile','Your impact, recognised.','Demo outcomes are recorded only after a simulated receipt confirmation.')+`<div class="stats"><div class="stat"><small>EDIBLE FOOD REDISTRIBUTED</small><strong>${edible} kg</strong></div><div class="stat"><small>ORGANICS RECOVERED</small><strong>${organic} kg</strong></div><div class="stat"><small>REWARD BALANCE</small><strong>${state.points} pts</strong></div></div><div class="grid"><div class="card"><span class="eyebrow">Pilot reward</span><h2>$20 collection voucher</h2><p>Use 200 points towards your next collection. Illustrative sponsor-funded reward.</p><div class="progress"><i style="width:${Math.min(100,state.points/2)}%"></i></div><button ${state.redeemed||state.points<200?'disabled':''} onclick="redeem()">${state.redeemed?'Voucher redeemed':state.points<200?`${200-state.points} more points needed`:'Redeem 200 points'}</button></div><div class="card"><h2>Reward the outcome</h2><p>The demo adds 100 points per confirmed handover. Your starting balance is 120 points.</p><p>Production rewards would require verified quantities and safeguards against duplicate claims.</p><span class="badge">Participation rewards · not carbon credits</span></div></div><div class="card" style="margin-top:22px"><h2>Prevention comes first</h2><p>Redistribution and organics recovery are tracked separately. Waste prevented would be measured against an agreed baseline; no prevention or emissions savings are claimed by this demo.</p><button onclick="exportData()">Download activity CSV</button></div>`}else{app.innerHTML=head('A useful destination for every stream','Keep unavoidable organics in circulation.','Choose a recovery partner based on the material they can accept.')+`<div class="grid">${[{name:'Western Soil Collective',type:'Composting',text:'Accepts separated fruit and vegetable scraps. No plastic, packaging or liquids.',icon:'🌱'},{name:'Circular Energy Hub',type:'Anaerobic digestion',text:'Accepts separated produce residues. Contamination and intake capacity require confirmation.',icon:'♻️'}].map((p,n)=>`<div class="card"><div class="produce" style="width:65px">${p.icon}</div><h2>${p.name}</h2><span class="badge">${p.type}</span><p>${p.text}</p><button class="primary" onclick="recovery(${n})">Request collection</button></div>`).join('')}</div><div class="banner"><div><h2>Is it still safe and suitable to eat?</h2><p>Explore food redistribution before choosing organics treatment.</p></div><button onclick="go('discover')">Find a food partner</button></div>`}}function open(html){modal.innerHTML='<button class="close" onclick="modal.close()" aria-label="Close dialog">×</button>'+html;modal.showModal()}function listing(type='Surplus'){open(`<h2>Create a listing</h2><p>Share what you have, or what you need.</p><form id="listing"><label>Listing type</label><select name="type"><option ${type==='Surplus'?'selected':''}>Surplus</option><option ${type==='Demand'?'selected':''}>Demand</option></select><label>Produce</label><input name="name" required maxlength="80" placeholder="e.g. Field-grown tomatoes"><label>Quantity (kg)</label><input name="qty" type="number" min="1" max="100000" required><label>Location</label><input name="place" required maxlength="60" placeholder="e.g. Werribee"><label>Availability / needed by</label><input name="time" type="date" required><label>Handling requirements</label><input name="handling" required maxlength="160" placeholder="e.g. Chilled collection, packed in crates"><div class="actions"><button class="primary">Publish demo listing</button></div></form>`);document.querySelector('#listing').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));state.items.unshift({...d,qty:+d.qty,id:Date.now(),org:'Westside Growers',icon:'🥬',x:35,y:65});save();modal.close();go('discover');toast('Your listing is visible in this browser.') }}function detail(id){const i=state.items.find(i=>i.id===id);open(`<div class="produce" style="width:65px">${i.icon}</div><span class="badge">${i.type}</span><h2>${esc(i.name)}</h2><p>${esc(i.org)} · ${esc(i.place)}</p><div class="stat"><strong>${i.qty} kg</strong><small>${esc(i.time)}</small></div><p>${esc(i.handling||'Produce in reusable crates. Collection timing and food suitability must be confirmed with the partner.')}</p><form id="match"><label>Quantity to ${i.type==='Demand'?'supply':'request'} (kg)</label><input name="qty" type="number" required min="1" max="${i.qty}" value="${Math.min(200,i.qty)}"><div class="actions"><button class="primary">Request connection</button></div></form><small>Demo only. No partner will be contacted.</small>`);document.querySelector('#match').onsubmit=e=>{e.preventDefault();let qty=+new FormData(e.target).get('qty');state.activity.unshift({name:i.name,partner:i.org,qty,done:false});i.qty-=qty;if(!i.qty)state.items=state.items.filter(x=>x.id!==id);save();modal.close();go('activity');toast('Connection saved. Confirm receipt after collection.')}}function complete(n){state.activity[n].done=true;state.points+=100;save();render();toast('Receipt confirmed. 100 demo points added.')}function redeem(){if(state.points<200||state.redeemed)return;state.points-=200;state.redeemed=true;save();render();toast('Demo voucher: LOOP20 · no monetary value')}function recovery(n){let partner=n?'Circular Energy Hub':'Western Soil Collective';open(`<h2>Request organics collection</h2><p>${partner}</p><form id="recover"><label>Material</label><select name="material"><option>Fruit and vegetable scraps</option><option>Produce processing residues</option></select><label>Quantity (kg)</label><input name="qty" type="number" min="1" max="100000" required><label>Collection date</label><input type="date" required><label><input type="checkbox" required style="width:auto"> Separated from packaging and other contaminants</label><button class="primary">Save collection request</button></form><p><small>Demo booking only. Partner acceptance is simulated.</small></p>`);document.querySelector('#recover').onsubmit=e=>{e.preventDefault();let d=new FormData(e.target);state.activity.unshift({name:d.get('material'),partner,qty:+d.get('qty'),route:n?'Anaerobic digestion':'Composting',done:false});save();modal.close();go('activity');toast('Collection request saved.')}}function exportData(){const cell=x=>'"'+String(x).replace(/"/g,'""').replace(/^[=+@-]/,"'")+'"';const rows=[['Produce','Partner','Quantity kg','Route','Status'],...state.activity.map(a=>[a.name,a.partner,a.qty,a.route||'Redistribution',a.done?'Confirmed':'Pending'])];const url=URL.createObjectURL(new Blob([rows.map(r=>r.map(cell).join(',')).join('\n')],{type:'text/csv'}));let a=document.createElement('a');a.href=url;a.download='foodloop-demo-activity.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}render();
